Problem:
A fitness trainer meal-preps two types of meals, a salmon lunch and a bison burger. The salmon lunch contains 15 grams of protein, 20 grams of carbs, and 8 grams of fat. The bison burger contains 30 grams of protein, 20 grams of carbs, and 13 grams of fat. The fitness trainer wants to get at least 160 grams of protein and 180 grams of carbs. In addition, because the salmon lunch is expensive, at most 25% of the meals should be salmon lunch. How many of each meal should he eat if he wants to minimize his fat intake?

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "salmon lunches",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "bison burgers",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "min",
   "terms": [
    {
     "var": "salmon lunches",
     "coef": 8.0
    },
    {
     "var": "bison burgers",
     "coef": 13.0
    }
   ]
  },
  "constraints": [
   {
    "name": "protein",
    "terms": [
     {
      "var": "salmon lunches",
      "coef": 15.0
     },
     {
      "var": "bison burgers",
      "coef": 30.0
     }
    ],
    "sense": ">=",
    "rhs": 160.0
   },
   {
    "name": "carbs",
    "terms": [
     {
      "var": "salmon lunches",
      "coef": 20.0
     },
     {
      "var": "bison burgers",
      "coef": 20.0
     }
    ],
    "sense": ">=",
    "rhs": 180.0
   },
   {
    "name": "salmon share at most 25 percent",
    "terms": [
     {
      "var": "salmon lunches",
      "coef": 0.75
     },
     {
      "var": "bison burgers",
      "coef": -0.25
     }
    ],
    "sense": "<=",
    "rhs": 0.0
   }
  ]
 },
 "facts": {
  "objective": 107.0,
  "values": {
   "salmon lunches": 2.0,
   "bison burgers": 7.0
  },
  "binding": [
   "carbs"
  ],
  "slack": {
   "protein": 80.0,
   "carbs": 0.0,
   "salmon share at most 25 percent": 0.25
  },
  "shadow_prices": null
 }
}
